def transform(grid):
    """Fill zero interiors of rectangular color-2 frames using demo-derived color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            comp = {(r, c)}
            seen.add((r, c))
            q = deque([(r, c)])
            while q:
                rr, cc = q.popleft()
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr,nc) not in seen:
                        seen.add((nr,nc)); comp.add((nr,nc)); q.append((nr,nc))
            r0, r1 = min(x for x,y in comp), max(x for x,y in comp)
            c0, c1 = min(y for x,y in comp), max(y for x,y in comp)
            if (r1-r0 >= 2 and c1-c0 >= 2
                and all((rr,c0) in comp and (rr,c1) in comp for rr in range(r0,r1+1))
